const { useState } = React;

function Navbar({ currentPage, onNavigate }) {
  return (
    <header style={styles.navbar}>
      <div style={styles.logo}>Acme</div>
      <nav style={styles.navLinks} aria-label="Primary">
        <button
          style={currentPage === 'dashboard' ? styles.navLinkActive : styles.navLink}
          onClick={() => onNavigate('dashboard')}
          aria-current={currentPage === 'dashboard' ? 'page' : undefined}
        >
          Home
        </button>
        <button
          style={currentPage === 'reports' ? styles.navLinkActive : styles.navLink}
          onClick={() => onNavigate('reports')}
          aria-current={currentPage === 'reports' ? 'page' : undefined}
        >
          Reports
        </button>
        <button
          style={currentPage === 'settings' ? styles.navLinkActive : styles.navLink}
          onClick={() => onNavigate('settings')}
          aria-current={currentPage === 'settings' ? 'page' : undefined}
        >
          Settings
        </button>
      </nav>
      <button aria-label="User account" style={styles.userIcon}>
        <svg
          xmlns="http://www.w3.org/2000/svg"
          fill="none"
          viewBox="0 0 24 24"
          strokeWidth={2}
          stroke="currentColor"
          aria-hidden="true"
          style={{ width: 24, height: 24 }}
        >
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            d="M5.121 17.804A9 9 0 1118.879 6.196 9 9 0 015.12 17.804z"
          />
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            d="M15 11a3 3 0 11-6 0 3 3 0 016 0z"
          />
        </svg>
      </button>
    </header>
  );
}

function StatCard({ value, label }) {
  return (
    <section style={styles.statCard} aria-label={`${label} stat` }>
      <p style={styles.statValue}>{value}</p>
      <p style={styles.statLabel}>{label}</p>
    </section>
  );
}

function SalesChart() {
  // Simple SVG line chart with fixed data points
  const points = [10, 30, 50, 45, 30, 20, 25];
  const max = Math.max(...points);
  const svgPoints = points
    .map((p, i) => `${i * 40 + 10},${60 - (p / max) * 50}`)
    .join(' ');

  return (
    <section style={styles.salesCard} aria-label="Sales chart">
      <h3 style={styles.cardTitle}>Sales</h3>
      <svg
        width="280"
        height="70"
        aria-hidden="true"
        style={{ display: 'block', marginTop: 8 }}
      >
        <polyline
          fill="none"
          stroke="#3b82f6"
          strokeWidth="2"
          points={svgPoints}
        />
        <line x1="10" y1="60" x2="270" y2="60" stroke="#ccc" strokeWidth="1" />
        <line x1="10" y1="10" x2="10" y2="60" stroke="#ccc" strokeWidth="1" />
      </svg>
    </section>
  );
}

function RecentOrders() {
  const orders = [1042, 1041, 1040, 1039];
  return (
    <section style={styles.recentOrders} aria-label="Recent orders">
      <h3 style={styles.cardTitle}>Recent orders</h3>
      <ul style={styles.orderList}>
        {orders.map((order) => (
          <li key={order} style={styles.orderItem}>
            Order {order}
          </li>
        ))}
      </ul>
    </section>
  );
}

function Dashboard() {
  return (
    <main style={styles.main}>
      <h2 style={styles.heading}>Dashboard</h2>
      <section style={styles.statsRow} aria-label="Statistics">
        <StatCard value="1,240" label="Users" />
        <StatCard value="$8,300" label="Revenue" />
        <StatCard value="312" label="Orders" />
      </section>
      <section style={styles.contentRow}>
        <SalesChart />
        <RecentOrders />
      </section>
    </main>
  );
}

function Reports() {
  return (
    <main style={styles.main}>
      <h2 style={styles.heading}>Reports</h2>
      <p>This is the Reports page.</p>
    </main>
  );
}

function Settings() {
  return (
    <main style={styles.main}>
      <h2 style={styles.heading}>Settings</h2>
      <p>This is the Settings page.</p>
    </main>
  );
}

